/**
 * Arlo UI — Chart
 *
 * A single-series line/area chart you scrub with your finger, for the "how is this
 * number doing" screen: a portfolio, a balance, a metric over time.
 *
 *   <Chart data={points} periods={['1D','1W','1M','1Y','ALL']} period={p} onPeriodChange={setP}>
 *     <Chart.Value format={money} />
 *     <Chart.Delta format={money} />
 *     <Chart.Plot height={180} />
 *     <Chart.Periods />
 *   </Chart>
 *
 * The other four forms hang off the same namespace, each a complete chart rather
 * than a part of the one above:
 *
 *   <Chart.Sparkline data={points} />        inline line, no chrome
 *   <Chart.Bar data={bars} />                categorical bars
 *   <Chart.Donut data={slices} />            part-to-whole, legend required
 *   <Chart.Meter value={n} max={m} />        one value against a target
 *
 * Deliberate choices:
 *
 * - **No axis furniture.** No ticks, no gridlines, no axis labels. The value readout
 *   is the label, and it updates as you scrub. A chart at this size answers "shape
 *   and direction", not "what exactly was Tuesday".
 * - **Direction, not identity.** One series, so no legend and no categorical palette —
 *   the tone is `chartPositive` / `chartNegative`, chosen by whether the series ended
 *   above or below where it started (or the `baseline`).
 * - **Direction is never colour-alone.** `Chart.Delta` always renders a sign, because
 *   the two tones sit near the deuteranopia separation floor. Don't render a bare
 *   coloured number instead.
 * - **Straight segments.** The path is not smoothed: a spline through sparse points
 *   invents peaks and troughs that were never in the data.
 *
 * The value and delta read from context, so they show the scrubbed point while a
 * drag is active and fall back to the latest point when it isn't.
 */
import {
  createContext,
  useCallback,
  useContext,
  useId,
  useMemo,
  useState,
  type ReactNode,
} from 'react';
import {
  PanResponder,
  Platform,
  Pressable,
  Text,
  View,
  type LayoutChangeEvent,
  type StyleProp,
  type TextStyle,
  type ViewStyle,
} from 'react-native';
import Svg, { Circle, Defs, LinearGradient, Path, Stop } from 'react-native-svg';
import { AnimatedCounter } from '../animated-counter/animated-counter';
import { useTokens } from '../../foundation/theme-provider';
import { BarChart } from './bar-chart';
import { DonutChart } from './donut-chart';
import { Meter } from './meter';
import { Sparkline } from './sparkline';

export type ChartTone = 'auto' | 'positive' | 'negative' | 'neutral';

type ChartContextValue = {
  data: number[];
  /** Index under the finger, or `null` when nothing is being scrubbed. */
  activeIndex: number | null;
  setActiveIndex: (index: number | null) => void;
  /** The point the readout should show: the scrubbed one, else the last. */
  displayIndex: number;
  color: string;
  baseline: number;
  first: number;
  last: number;
  min: number;
  max: number;
  periods: string[];
  period?: string;
  onPeriodChange?: (period: string) => void;
};

const ChartContext = createContext<ChartContextValue | null>(null);

function useChart(): ChartContextValue {
  const ctx = useContext(ChartContext);
  if (!ctx) throw new Error('Chart.* must be rendered inside <Chart>');
  return ctx;
}

export type ChartProps = {
  /** The series, oldest first. Needs at least two points to draw a line. */
  data: number[];
  children: ReactNode;
  /**
   * `'auto'` tones by whether the series ended above or below `baseline`
   * (defaults to the first point). Force it when the series' own direction isn't
   * the story — e.g. spending, where "up" is bad.
   */
  tone?: ChartTone;
  /** Reference value for tone and for the dashed baseline. Defaults to the first point. */
  baseline?: number;
  periods?: string[];
  period?: string;
  onPeriodChange?: (period: string) => void;
  style?: StyleProp<ViewStyle>;
};

function ChartRoot({
  data,
  children,
  tone = 'auto',
  baseline: baselineProp,
  periods = [],
  period,
  onPeriodChange,
  style,
}: ChartProps) {
  const t = useTokens();
  const [activeIndex, setActiveIndex] = useState<number | null>(null);

  const stats = useMemo(() => {
    const head = data[0];
    if (head == null) return { first: 0, last: 0, min: 0, max: 0 };
    let min = head;
    let max = head;
    for (const value of data) {
      if (value < min) min = value;
      if (value > max) max = value;
    }
    return { first: head, last: data[data.length - 1] ?? head, min, max };
  }, [data]);

  const baseline = baselineProp ?? stats.first;

  const color =
    tone === 'neutral'
      ? t.colors.textPrimary
      : tone === 'positive'
        ? t.colors.chartPositive
        : tone === 'negative'
          ? t.colors.chartNegative
          : stats.last >= baseline
            ? t.colors.chartPositive
            : t.colors.chartNegative;

  const displayIndex = activeIndex ?? Math.max(0, data.length - 1);

  const ctx = useMemo<ChartContextValue>(
    () => ({
      data,
      activeIndex,
      setActiveIndex,
      displayIndex,
      color,
      baseline,
      periods,
      period,
      onPeriodChange,
      ...stats,
    }),
    [data, activeIndex, displayIndex, color, baseline, periods, period, onPeriodChange, stats],
  );

  return (
    <ChartContext.Provider value={ctx}>
      <View style={[{ gap: t.spacing[2] }, style]}>{children}</View>
    </ChartContext.Provider>
  );
}

/** The headline number. Rolls between values as you scrub. */
function ChartValue({
  format,
  style,
}: {
  format?: (value: number) => string;
  /** Wraps the counter, so this is a view style — the type ramp comes from tokens. */
  style?: StyleProp<ViewStyle>;
}) {
  const t = useTokens();
  const { data, displayIndex } = useChart();
  const value = data[displayIndex] ?? 0;
  const text = format ? format(value) : String(value);

  return (
    <View style={[{ alignItems: 'flex-start' }, style]}>
      <AnimatedCounter
        text={text}
        fontSize={t.typography.displayMedium.fontSize}
        lineHeight={t.typography.displayMedium.lineHeight}
        // Ink, not the series colour — the line already carries direction.
        color={t.colors.textPrimary}
        fontFamily={t.fontFamilies.sans}
        fontWeight="700"
      />
    </View>
  );
}

/**
 * Change from the baseline to the shown point. Always renders an explicit sign —
 * that sign is what keeps direction readable when the two tones are hard to tell
 * apart, so don't strip it.
 */
function ChartDelta({
  format,
  showPercent = true,
  style,
}: {
  format?: (value: number) => string;
  showPercent?: boolean;
  style?: StyleProp<TextStyle>;
}) {
  const t = useTokens();
  const { data, displayIndex, baseline, color } = useChart();
  const value = data[displayIndex] ?? 0;
  const change = value - baseline;
  const sign = change > 0 ? '+' : change < 0 ? '−' : '';
  const magnitude = Math.abs(change);
  const percent = baseline === 0 ? 0 : (change / Math.abs(baseline)) * 100;
  const formatted = format ? format(magnitude) : String(magnitude);

  return (
    <Text
      style={[
        {
          color,
          fontFamily: t.fontFamilies.sans,
          fontSize: t.typography.body.fontSize,
          lineHeight: t.typography.body.lineHeight,
          fontWeight: '600',
        },
        style,
      ]}
    >
      {sign}
      {formatted}
      {showPercent ? ` (${sign}${Math.abs(percent).toFixed(2)}%)` : ''}
    </Text>
  );
}

export type ChartPlotProps = {
  height?: number;
  /** Fade a gradient under the line. */
  fill?: boolean;
  /** Dashed line at the baseline value. */
  showBaseline?: boolean;
  /** Turn off scrubbing for a static, decorative plot. */
  scrubbable?: boolean;
  /** Announced by screen readers in place of the visual plot. */
  accessibilityLabel?: string;
  style?: StyleProp<ViewStyle>;
};

const STROKE = 2;
/** Room for the stroke and the scrub dot so neither clips at the edges. */
const INSET = 6;

function ChartPlot({
  height = 180,
  fill = true,
  showBaseline = true,
  scrubbable = true,
  accessibilityLabel,
  style,
}: ChartPlotProps) {
  const t = useTokens();
  const { data, activeIndex, setActiveIndex, color, baseline, min, max, first, last } = useChart();
  const [width, setWidth] = useState(0);

  const count = data.length;

  const handleLayout = useCallback((event: LayoutChangeEvent) => {
    setWidth(event.nativeEvent.layout.width);
  }, []);

  // Depends on live layout rather than a render-written ref. The responder is
  // rebuilt when either changes; an in-flight gesture keeps the handlers it was
  // granted with, which is fine since width settles on first layout.
  const indexAt = useCallback(
    (x: number) => {
      if (count < 2 || width <= INSET * 2) return 0;
      const usable = width - INSET * 2;
      const ratio = (x - INSET) / usable;
      const index = Math.round(ratio * (count - 1));
      return Math.min(count - 1, Math.max(0, index));
    },
    [count, width],
  );

  const panResponder = useMemo(
    () =>
      PanResponder.create({
        onStartShouldSetPanResponder: () => scrubbable,
        onMoveShouldSetPanResponder: () => scrubbable,
        // Claim the gesture so a parent ScrollView doesn't steal a horizontal drag.
        onPanResponderTerminationRequest: () => false,
        onPanResponderGrant: (event) => setActiveIndex(indexAt(event.nativeEvent.locationX)),
        onPanResponderMove: (event) => setActiveIndex(indexAt(event.nativeEvent.locationX)),
        onPanResponderRelease: () => setActiveIndex(null),
        onPanResponderTerminate: () => setActiveIndex(null),
      }),
    [indexAt, setActiveIndex, scrubbable],
  );

  const plotHeight = height;
  const usableWidth = Math.max(0, width - INSET * 2);
  const usableHeight = Math.max(0, plotHeight - INSET * 2);
  // A flat series has no range to normalise against; draw it down the middle
  // instead of dividing by zero.
  const span = max - min;

  const pointAt = useCallback(
    (index: number) => {
      const count = data.length;
      const x = count < 2 ? INSET + usableWidth / 2 : INSET + (index / (count - 1)) * usableWidth;
      const ratio = span === 0 ? 0.5 : ((data[index] ?? min) - min) / span;
      const y = INSET + (1 - ratio) * usableHeight;
      return { x, y };
    },
    [data, min, span, usableWidth, usableHeight],
  );

  const linePath = useMemo(() => {
    if (data.length === 0 || width === 0) return '';
    return data
      .map((_, index) => {
        const { x, y } = pointAt(index);
        return `${index === 0 ? 'M' : 'L'}${x.toFixed(2)},${y.toFixed(2)}`;
      })
      .join(' ');
  }, [data, pointAt, width]);

  const areaPath = useMemo(() => {
    if (!fill || !linePath || data.length < 2) return '';
    const start = pointAt(0);
    const end = pointAt(data.length - 1);
    const floor = plotHeight - INSET;
    return `${linePath} L${end.x.toFixed(2)},${floor} L${start.x.toFixed(2)},${floor} Z`;
  }, [fill, linePath, data.length, pointAt, plotHeight]);

  const baselineY = useMemo(() => {
    const ratio = span === 0 ? 0.5 : (baseline - min) / span;
    return INSET + (1 - ratio) * usableHeight;
  }, [baseline, min, span, usableHeight]);

  const showBaselineLine =
    showBaseline && data.length > 1 && baseline >= min && baseline <= max && span > 0;

  const active = activeIndex != null ? pointAt(activeIndex) : null;

  // Document-global, so a constant id would collide between two charts on one screen.
  const gradientId = `arloChartFill-${useId().replace(/[^a-zA-Z0-9]/g, '')}`;

  const summary =
    accessibilityLabel ??
    `Line chart, ${data.length} points, from ${first} to ${last}, low ${min}, high ${max}`;

  return (
    <View
      onLayout={handleLayout}
      accessible
      accessibilityRole="image"
      accessibilityLabel={summary}
      style={[{ height: plotHeight, width: '100%' }, style]}
      {...(scrubbable ? panResponder.panHandlers : {})}
    >
      {width > 0 && data.length > 0 ? (
        <Svg width={width} height={plotHeight}>
          {fill ? (
            <Defs>
              <LinearGradient id={gradientId} x1="0" y1="0" x2="0" y2="1">
                <Stop offset="0" stopColor={color} stopOpacity={0.22} />
                <Stop offset="1" stopColor={color} stopOpacity={0} />
              </LinearGradient>
            </Defs>
          ) : null}

          {showBaselineLine ? (
            <Path
              d={`M${INSET},${baselineY.toFixed(2)} L${(width - INSET).toFixed(2)},${baselineY.toFixed(2)}`}
              stroke={t.colors.border}
              strokeWidth={1}
              strokeDasharray="3 4"
            />
          ) : null}

          {areaPath ? <Path d={areaPath} fill={`url(#${gradientId})`} /> : null}

          <Path
            d={linePath}
            stroke={color}
            strokeWidth={STROKE}
            strokeLinecap="round"
            strokeLinejoin="round"
            fill="none"
          />

          {active ? (
            <>
              <Path
                d={`M${active.x.toFixed(2)},${INSET} L${active.x.toFixed(2)},${(plotHeight - INSET).toFixed(2)}`}
                stroke={t.colors.border}
                strokeWidth={1}
              />
              {/* Surface ring keeps the dot readable where it overlaps the line. */}
              <Circle cx={active.x} cy={active.y} r={6} fill={color} stroke={t.colors.surface} strokeWidth={2} />
            </>
          ) : null}
        </Svg>
      ) : null}
    </View>
  );
}

/** Time-range selector. Renders nothing when the chart was given no `periods`. */
function ChartPeriods({ style }: { style?: StyleProp<ViewStyle> }) {
  const t = useTokens();
  const { periods, period, onPeriodChange, color } = useChart();
  if (periods.length === 0) return null;

  return (
    <View
      accessibilityRole="tablist"
      style={[{ flexDirection: 'row', alignItems: 'center', gap: t.spacing[1] }, style]}
    >
      {periods.map((option) => {
        const selected = option === period;
        return (
          <Pressable
            key={option}
            accessibilityRole="tab"
            accessibilityLabel={option}
            accessibilityState={{ selected }}
            onPress={() => onPeriodChange?.(option)}
            hitSlop={8}
            style={({ pressed }) => ({
              flex: 1,
              minHeight: 32,
              paddingHorizontal: t.spacing[2],
              alignItems: 'center',
              justifyContent: 'center',
              borderRadius: t.radii.md,
              backgroundColor: selected ? t.colors.surfaceInput : 'transparent',
              opacity: pressed ? t.motion.pressed.opacity : 1,
              cursor: Platform.OS === 'web' ? 'pointer' : undefined,
            })}
          >
            <Text
              style={{
                color: selected ? color : t.colors.textSecondary,
                fontFamily: t.fontFamilies.sans,
                fontSize: t.typography.bodySm.fontSize,
                lineHeight: t.typography.bodySm.lineHeight,
                fontWeight: selected ? '700' : '500',
              }}
            >
              {option}
            </Text>
          </Pressable>
        );
      })}
    </View>
  );
}

/**
 * `Value`/`Delta`/`Plot`/`Periods` compose the scrubbable chart above; `Sparkline`,
 * `Bar`, `Donut`, and `Meter` are whole charts in their own right, namespaced here
 * so picking a form is one decision at one import rather than four names to
 * remember. They stay in their own files — import those directly if you only
 * copied one form into your project.
 */
export const Chart = Object.assign(ChartRoot, {
  Value: ChartValue,
  Delta: ChartDelta,
  Plot: ChartPlot,
  Periods: ChartPeriods,
  Sparkline,
  Bar: BarChart,
  Donut: DonutChart,
  Meter,
});

/**
 * Arlo UI — Sparkline
 *
 * A line with everything else removed: no axes, no labels, no scrub, no legend.
 * It belongs inline — beside a number in a stat card, inside a table row — where
 * the surrounding text already says what the number is and the shape is the only
 * thing the mark has to carry.
 *
 * If you want a value readout, a baseline, or scrubbing, you want `Chart`.
 */
import { useId, useMemo, useState } from 'react';
import { View, type LayoutChangeEvent, type StyleProp, type ViewStyle } from 'react-native';
import Svg, { Circle, Defs, LinearGradient, Path, Stop } from 'react-native-svg';
import { useTokens } from '../../foundation/theme-provider';
import type { ChartTone } from './chart';

export type SparklineProps = {
  data: number[];
  /** Matches `Chart`: `'auto'` tones by whether the series ended above where it started. */
  tone?: ChartTone;
  width?: number;
  height?: number;
  /** Fade a gradient under the line. Off by default — inline marks stay light. */
  fill?: boolean;
  /** Dot on the final point, for "where it ended up". */
  showEndDot?: boolean;
  strokeWidth?: number;
  /**
   * Sparklines are decorative next to a value that is already announced, so they
   * are hidden from assistive tech unless you pass a label.
   */
  accessibilityLabel?: string;
  style?: StyleProp<ViewStyle>;
};

const INSET = 3;

export function Sparkline({
  data,
  tone = 'auto',
  width: widthProp,
  height = 28,
  fill = false,
  showEndDot = false,
  strokeWidth = 2,
  accessibilityLabel,
  style,
}: SparklineProps) {
  const t = useTokens();
  const [measured, setMeasured] = useState(0);
  const width = widthProp ?? measured;

  const { min, span, first, last } = useMemo(() => {
    const head = data[0];
    if (head == null) return { min: 0, span: 0, first: 0, last: 0 };
    let lo = head;
    let hi = head;
    for (const v of data) {
      if (v < lo) lo = v;
      if (v > hi) hi = v;
    }
    return { min: lo, span: hi - lo, first: head, last: data[data.length - 1] ?? head };
  }, [data]);

  const color =
    tone === 'neutral'
      ? t.colors.textSecondary
      : tone === 'positive'
        ? t.colors.chartPositive
        : tone === 'negative'
          ? t.colors.chartNegative
          : last >= first
            ? t.colors.chartPositive
            : t.colors.chartNegative;

  const usableW = Math.max(0, width - INSET * 2);
  const usableH = Math.max(0, height - INSET * 2);

  const points = useMemo(() => {
    if (width === 0 || data.length === 0) return [];
    return data.map((value, index) => {
      const x = data.length < 2 ? INSET + usableW / 2 : INSET + (index / (data.length - 1)) * usableW;
      // A flat series has no range to normalise against, so it runs down the middle.
      const ratio = span === 0 ? 0.5 : (value - min) / span;
      return { x, y: INSET + (1 - ratio) * usableH };
    });
  }, [data, width, usableW, usableH, min, span]);

  const linePath = points
    .map((p, i) => `${i === 0 ? 'M' : 'L'}${p.x.toFixed(2)},${p.y.toFixed(2)}`)
    .join(' ');
  const end = points[points.length - 1];
  const start = points[0];
  const areaPath =
    fill && linePath && start && end
      ? `${linePath} L${end.x.toFixed(2)},${height - INSET} L${start.x.toFixed(2)},${height - INSET} Z`
      : '';

  // Per instance, not per tone: two `tone="auto"` sparklines on one screen resolve
  // to different colours but would share one document-global gradient id, so the
  // first definition would win and paint both fills the same.
  const gradientId = `arloSparkFill-${useId().replace(/[^a-zA-Z0-9]/g, '')}`;

  return (
    <View
      onLayout={
        widthProp == null
          ? (event: LayoutChangeEvent) => setMeasured(event.nativeEvent.layout.width)
          : undefined
      }
      accessible={accessibilityLabel != null}
      accessibilityRole={accessibilityLabel != null ? 'image' : undefined}
      accessibilityLabel={accessibilityLabel}
      accessibilityElementsHidden={accessibilityLabel == null}
      importantForAccessibility={accessibilityLabel == null ? 'no-hide-descendants' : 'auto'}
      style={[{ width: widthProp, height }, style]}
    >
      {width > 0 && points.length > 0 ? (
        <Svg width={width} height={height}>
          {areaPath ? (
            <>
              <Defs>
                <LinearGradient id={gradientId} x1="0" y1="0" x2="0" y2="1">
                  <Stop offset="0" stopColor={color} stopOpacity={0.24} />
                  <Stop offset="1" stopColor={color} stopOpacity={0} />
                </LinearGradient>
              </Defs>
              <Path d={areaPath} fill={`url(#${gradientId})`} />
            </>
          ) : null}
          <Path
            d={linePath}
            stroke={color}
            strokeWidth={strokeWidth}
            strokeLinecap="round"
            strokeLinejoin="round"
            fill="none"
          />
          {showEndDot && end ? <Circle cx={end.x} cy={end.y} r={strokeWidth + 0.5} fill={color} /> : null}
        </Svg>
      ) : null}
    </View>
  );
}

/**
 * Arlo UI — BarChart
 *
 * Categorical magnitude: spend per day, sessions per channel. Bars are the right
 * form when the categories are discrete and the comparison is "which is bigger" —
 * use `Chart` instead when the x-axis is continuous time.
 *
 *   <BarChart data={[{ label: 'M', value: 32 }, { label: 'T', value: 18 }]} />
 *
 * Deliberate choices:
 *
 * - **Data-ends are rounded, the baseline end is not.** A bar is anchored to its
 *   axis; rounding the anchored end would lift it off and misreport where zero is.
 * - **Negatives drop below the baseline** rather than being drawn as magnitudes,
 *   and the baseline moves to wherever zero falls.
 * - **One hue by default.** A bar chart of one measure is magnitude, not identity,
 *   so it does not spend the categorical palette; pass `tone="series"` for the
 *   case where each bar really is a different thing.
 * - **Selection instead of hover.** Tapping a bar reports it and shows its value;
 *   there is no hover on a touch screen.
 */
import { useMemo, useState } from 'react';
import {
  Pressable,
  Text,
  View,
  type LayoutChangeEvent,
  type StyleProp,
  type ViewStyle,
} from 'react-native';
import { useTokens } from '../../foundation/theme-provider';

export type BarDatum = {
  label: string;
  value: number;
  /** Overrides the resolved colour for this bar alone. */
  color?: string;
};

export type BarChartTone = 'brand' | 'series' | 'direction';

export type BarChartProps = {
  data: BarDatum[];
  height?: number;
  tone?: BarChartTone;
  /** Index of the selected bar. Leave undefined for an unselected chart. */
  selectedIndex?: number | null;
  onSelect?: (index: number, datum: BarDatum) => void;
  /** Show each bar's value above it. Off by default — a number on every mark is noise. */
  showValues?: boolean;
  /** Show the category label under each bar. */
  showLabels?: boolean;
  format?: (value: number) => string;
  /** Force the top of the scale; otherwise it comes from the data. */
  maxValue?: number;
  style?: StyleProp<ViewStyle>;
};

const BAR_RADIUS = 4;
const GAP = 2;
const LABEL_HEIGHT = 18;
const VALUE_HEIGHT = 16;

export function BarChart({
  data,
  height = 160,
  tone = 'brand',
  selectedIndex,
  onSelect,
  showValues = false,
  showLabels = true,
  format,
  maxValue,
  style,
}: BarChartProps) {
  const t = useTokens();
  const [width, setWidth] = useState(0);

  const series = useMemo(
    () => [t.colors.chartSeries1, t.colors.chartSeries2, t.colors.chartSeries3, t.colors.chartSeries4],
    [t.colors],
  );

  const { top, bottom } = useMemo(() => {
    if (data.length === 0) return { top: 0, bottom: 0 };
    let hi = 0;
    let lo = 0;
    for (const d of data) {
      if (d.value > hi) hi = d.value;
      if (d.value < lo) lo = d.value;
    }
    return { top: maxValue ?? hi, bottom: lo };
  }, [data, maxValue]);

  // The plot always includes zero, so bar lengths stay proportional to value.
  const span = top - bottom;
  const plotHeight = Math.max(
    0,
    height - (showLabels ? LABEL_HEIGHT : 0) - (showValues ? VALUE_HEIGHT : 0),
  );
  const zeroY = span === 0 ? plotHeight : (top / span) * plotHeight;

  function barColor(index: number, datum: BarDatum) {
    if (datum.color) return datum.color;
    if (tone === 'direction') {
      return datum.value < 0 ? t.colors.chartNegative : t.colors.chartPositive;
    }
    if (tone === 'series') {
      // Past the validated four, everything folds into one neutral rather than
      // cycling hues that would repeat identities.
      return index < series.length ? (series[index] as string) : t.colors.chartOther;
    }
    return t.colors.interactivePrimary;
  }

  const summary = `Bar chart, ${data.length} categories, ${data
    .map((d) => `${d.label} ${d.value}`)
    .join(', ')}`;

  // A container element and focusable children are mutually exclusive, so the
  // chart picks whichever is actually useful: when bars are tappable each one is
  // its own button, and when they aren't the whole chart is a single element
  // announcing the summary.
  const interactive = onSelect != null;

  return (
    <View
      onLayout={(e: LayoutChangeEvent) => setWidth(e.nativeEvent.layout.width)}
      accessible={!interactive}
      accessibilityRole={interactive ? undefined : 'image'}
      accessibilityLabel={interactive ? undefined : summary}
      style={[{ height, width: '100%' }, style]}
    >
      <View style={{ flex: 1, flexDirection: 'row', alignItems: 'stretch', gap: GAP }}>
        {data.map((datum, index) => {
          const selected = selectedIndex === index;
          const negative = datum.value < 0;
          const magnitude = span === 0 ? 0 : (Math.abs(datum.value) / span) * plotHeight;
          const color = barColor(index, datum);

          return (
            <Pressable
              key={`${datum.label}-${index}`}
              accessible={interactive}
              accessibilityRole={interactive ? 'button' : undefined}
              accessibilityLabel={
                interactive ? `${datum.label}, ${format ? format(datum.value) : datum.value}` : undefined
              }
              accessibilityState={interactive ? { selected } : undefined}
              disabled={!interactive}
              onPress={() => onSelect?.(index, datum)}
              style={{ flex: 1, justifyContent: 'flex-end' }}
            >
              {showValues ? (
                <Text
                  numberOfLines={1}
                  style={{
                    height: VALUE_HEIGHT,
                    textAlign: 'center',
                    color: t.colors.textSecondary,
                    fontFamily: t.fontFamilies.sans,
                    fontSize: 10,
                    lineHeight: VALUE_HEIGHT,
                    fontWeight: '600',
                  }}
                >
                  {format ? format(datum.value) : datum.value}
                </Text>
              ) : null}

              <View style={{ height: plotHeight, justifyContent: 'flex-start' }}>
                <View
                  style={{
                    position: 'absolute',
                    left: 0,
                    right: 0,
                    // Negatives hang below zero; positives rise to it.
                    top: negative ? zeroY : zeroY - magnitude,
                    height: Math.max(2, magnitude),
                    backgroundColor: color,
                    // Only the data end is rounded — the baseline end stays square
                    // so the bar reads as anchored to zero.
                    borderTopLeftRadius: negative ? 0 : BAR_RADIUS,
                    borderTopRightRadius: negative ? 0 : BAR_RADIUS,
                    borderBottomLeftRadius: negative ? BAR_RADIUS : 0,
                    borderBottomRightRadius: negative ? BAR_RADIUS : 0,
                    opacity: selectedIndex == null || selected ? 1 : 0.4,
                  }}
                />
              </View>

              {showLabels ? (
                <Text
                  numberOfLines={1}
                  style={{
                    height: LABEL_HEIGHT,
                    textAlign: 'center',
                    color: selected ? t.colors.textPrimary : t.colors.textTertiary,
                    fontFamily: t.fontFamilies.sans,
                    fontSize: 11,
                    lineHeight: LABEL_HEIGHT,
                    fontWeight: selected ? '700' : '500',
                  }}
                >
                  {datum.label}
                </Text>
              ) : null}
            </Pressable>
          );
        })}
      </View>

      {/* A zero rule only earns its place when the data actually crosses it. */}
      {bottom < 0 && width > 0 ? (
        <View
          pointerEvents="none"
          style={{
            position: 'absolute',
            left: 0,
            right: 0,
            top: (showValues ? VALUE_HEIGHT : 0) + zeroY,
            height: 1,
            backgroundColor: t.colors.border,
          }}
        />
      ) : null}
    </View>
  );
}

/**
 * Arlo UI — DonutChart
 *
 * Part-to-whole: what a total is made of. Use it when the parts sum to something
 * meaningful and there are only a few of them — past a handful, a bar chart ranks
 * better than a ring compares.
 *
 *   <DonutChart data={[{ label: 'Rent', value: 1200 }, { label: 'Food', value: 480 }]} />
 *
 * Deliberate choices:
 *
 * - **Four categories, then "Other".** The categorical palette has exactly four
 *   validated slots (see the `chartSeries*` tokens); every slice is on screen at
 *   once here, so they were checked on all pairs, not just neighbours. Anything
 *   past the fourth is summed into a neutral "Other" rather than given an
 *   invented fifth hue.
 * - **The legend is not optional.** Two or more series means identity can never be
 *   colour alone, so each slice is listed with its label and value.
 * - **A surface-coloured gap between slices**, so touching arcs stay separable
 *   even when two colours are close.
 * - **Center label, not slice labels.** Text inside thin arcs is unreadable; the
 *   middle holds the total.
 */
import { useMemo, useState } from 'react';
import { Pressable, Text, View, type StyleProp, type ViewStyle } from 'react-native';
import Svg, { G, Path } from 'react-native-svg';
import { useTokens } from '../../foundation/theme-provider';

export type DonutSlice = {
  label: string;
  value: number;
  color?: string;
};

export type DonutChartProps = {
  data: DonutSlice[];
  size?: number;
  /** Ring thickness. */
  thickness?: number;
  /** Big text in the middle. Defaults to the summed total. */
  centerValue?: string;
  centerLabel?: string;
  /** Index of the emphasised slice. */
  selectedIndex?: number | null;
  onSelect?: (index: number, slice: DonutSlice) => void;
  format?: (value: number) => string;
  showLegend?: boolean;
  /** Categories past the palette's capacity are folded into one neutral slice. */
  maxSlices?: number;
  accessibilityLabel?: string;
  style?: StyleProp<ViewStyle>;
};

/** Gap between slices, in degrees, painted as a stroke in the surface colour. */
const GAP_DEGREES = 1.5;

function polar(cx: number, cy: number, r: number, degrees: number) {
  const rad = ((degrees - 90) * Math.PI) / 180;
  return { x: cx + r * Math.cos(rad), y: cy + r * Math.sin(rad) };
}

/** SVG path for one ring segment between two angles. */
function arcPath(
  cx: number,
  cy: number,
  outer: number,
  inner: number,
  startAngle: number,
  endAngle: number,
): string {
  const sweep = endAngle - startAngle;
  // A full ring can't be drawn as one arc — the start and end points coincide, so
  // it collapses. Split it into two halves.
  if (sweep >= 360) {
    const half = startAngle + 180;
    return `${arcPath(cx, cy, outer, inner, startAngle, half)} ${arcPath(cx, cy, outer, inner, half, startAngle + 360)}`;
  }
  const largeArc = sweep > 180 ? 1 : 0;
  const o1 = polar(cx, cy, outer, startAngle);
  const o2 = polar(cx, cy, outer, endAngle);
  const i2 = polar(cx, cy, inner, endAngle);
  const i1 = polar(cx, cy, inner, startAngle);
  return [
    `M${o1.x.toFixed(2)},${o1.y.toFixed(2)}`,
    `A${outer},${outer} 0 ${largeArc} 1 ${o2.x.toFixed(2)},${o2.y.toFixed(2)}`,
    `L${i2.x.toFixed(2)},${i2.y.toFixed(2)}`,
    `A${inner},${inner} 0 ${largeArc} 0 ${i1.x.toFixed(2)},${i1.y.toFixed(2)}`,
    'Z',
  ].join(' ');
}

export function DonutChart({
  data,
  size = 180,
  thickness = 26,
  centerValue,
  centerLabel,
  selectedIndex,
  onSelect,
  format,
  showLegend = true,
  maxSlices = 4,
  accessibilityLabel,
  style,
}: DonutChartProps) {
  const t = useTokens();
  const [internalSelection, setInternalSelection] = useState<number | null>(null);
  const selection = selectedIndex !== undefined ? selectedIndex : internalSelection;

  const palette = useMemo(
    () => [t.colors.chartSeries1, t.colors.chartSeries2, t.colors.chartSeries3, t.colors.chartSeries4],
    [t.colors],
  );

  // Fold everything past the palette's validated capacity into one neutral slice
  // rather than inventing hues that would read as new identities.
  const slices = useMemo(() => {
    const positive = data.filter((d) => d.value > 0);
    const cap = Math.min(maxSlices, palette.length);
    if (positive.length <= cap) return positive;
    const kept = positive.slice(0, cap);
    const rest = positive.slice(cap).reduce((sum, d) => sum + d.value, 0);
    return rest > 0 ? [...kept, { label: 'Other', value: rest, color: t.colors.chartOther }] : kept;
  }, [data, maxSlices, palette.length, t.colors.chartOther]);

  const total = slices.reduce((sum, s) => sum + s.value, 0);

  const cx = size / 2;
  const cy = size / 2;
  const outer = size / 2;
  const inner = Math.max(0, outer - thickness);

  const segments = useMemo(() => {
    if (total <= 0) return [];
    let cursor = 0;
    return slices.map((slice, index) => {
      const sweep = (slice.value / total) * 360;
      const start = cursor;
      cursor += sweep;
      // Only inset for a gap when the slice is wide enough to survive it.
      const gap = slices.length > 1 && sweep > GAP_DEGREES * 2 ? GAP_DEGREES / 2 : 0;
      return {
        slice,
        index,
        d: arcPath(cx, cy, outer, inner, start + gap, cursor - gap),
        color:
          slice.color ??
          (index < palette.length ? (palette[index] as string) : t.colors.chartOther),
        percent: (slice.value / total) * 100,
      };
    });
  }, [slices, total, cx, cy, outer, inner, palette, t.colors.chartOther]);

  const summary =
    accessibilityLabel ??
    `Donut chart. ${slices
      .map((s) => `${s.label} ${total > 0 ? Math.round((s.value / total) * 100) : 0} percent`)
      .join(', ')}`;

  const resolvedCenterValue = centerValue ?? (format ? format(total) : String(total));

  return (
    <View style={[{ gap: t.spacing[4] }, style]}>
      <View
        accessible
        accessibilityRole="image"
        accessibilityLabel={summary}
        style={{ width: size, height: size, alignSelf: 'center', justifyContent: 'center', alignItems: 'center' }}
      >
        {segments.length > 0 ? (
          <Svg width={size} height={size} style={{ position: 'absolute' }}>
            <G>
              {segments.map((segment) => (
                <Path
                  key={`${segment.slice.label}-${segment.index}`}
                  d={segment.d}
                  fill={segment.color}
                  opacity={selection == null || selection === segment.index ? 1 : 0.35}
                  // Surface-coloured ring keeps adjacent arcs separable.
                  stroke={t.colors.surface}
                  strokeWidth={1}
                />
              ))}
            </G>
          </Svg>
        ) : (
          <View
            style={{
              position: 'absolute',
              width: size,
              height: size,
              borderRadius: size / 2,
              borderWidth: thickness,
              borderColor: t.colors.surfaceInput,
            }}
          />
        )}

        <View style={{ alignItems: 'center', paddingHorizontal: thickness }}>
          <Text
            numberOfLines={1}
            style={{
              color: t.colors.textPrimary,
              fontFamily: t.fontFamilies.sans,
              fontSize: t.typography.title2.fontSize,
              lineHeight: t.typography.title2.lineHeight,
              fontWeight: '700',
            }}
          >
            {resolvedCenterValue}
          </Text>
          {centerLabel ? (
            <Text
              numberOfLines={1}
              style={{
                color: t.colors.textSecondary,
                fontFamily: t.fontFamilies.sans,
                fontSize: t.typography.bodySm.fontSize,
                lineHeight: t.typography.bodySm.lineHeight,
              }}
            >
              {centerLabel}
            </Text>
          ) : null}
        </View>
      </View>

      {showLegend && segments.length > 0 ? (
        <View style={{ gap: t.spacing[2] }}>
          {segments.map((segment) => {
            const selected = selection === segment.index;
            return (
              <Pressable
                key={`legend-${segment.slice.label}-${segment.index}`}
                accessibilityRole="button"
                accessibilityLabel={`${segment.slice.label}, ${
                  format ? format(segment.slice.value) : segment.slice.value
                }, ${segment.percent.toFixed(0)} percent`}
                accessibilityState={{ selected }}
                disabled={!onSelect && selectedIndex !== undefined}
                onPress={() => {
                  if (onSelect) onSelect(segment.index, segment.slice);
                  else setInternalSelection(selected ? null : segment.index);
                }}
                style={{ flexDirection: 'row', alignItems: 'center', gap: t.spacing[2] }}
              >
                <View
                  style={{
                    width: 10,
                    height: 10,
                    borderRadius: 3,
                    backgroundColor: segment.color,
                  }}
                />
                <Text
                  numberOfLines={1}
                  style={{
                    flex: 1,
                    // Text stays in ink; the swatch beside it carries identity.
                    color: t.colors.textPrimary,
                    fontFamily: t.fontFamilies.sans,
                    fontSize: t.typography.bodySm.fontSize,
                    lineHeight: t.typography.bodySm.lineHeight,
                    fontWeight: selected ? '700' : '500',
                  }}
                >
                  {segment.slice.label}
                </Text>
                <Text
                  style={{
                    color: t.colors.textSecondary,
                    fontFamily: t.fontFamilies.sans,
                    fontSize: t.typography.bodySm.fontSize,
                    lineHeight: t.typography.bodySm.lineHeight,
                    fontWeight: '600',
                  }}
                >
                  {format ? format(segment.slice.value) : segment.slice.value}
                </Text>
              </Pressable>
            );
          })}
        </View>
      ) : null}
    </View>
  );
}

/**
 * Arlo UI — Meter
 *
 * One value against a target: budget used, storage filled, goal progress. This is
 * a magnitude, not a category, so it is a single hue rather than a series colour —
 * and a `bar` or a `ring`, which are the same data with different shapes.
 *
 *   <Meter value={72} max={100} label="Storage" />
 *   <Meter shape="ring" value={1840} max={2000} label="Steps" tone="positive" />
 *
 * Passing `warnAt` / `dangerAt` moves it onto the status palette, which is
 * reserved for state and always ships with a visible value — never colour alone.
 */
import { useEffect, useMemo, useState } from 'react';
import {
  AccessibilityInfo,
  Animated,
  Easing,
  Text,
  View,
  type StyleProp,
  type ViewStyle,
} from 'react-native';
import Svg, { Circle } from 'react-native-svg';
import { useTokens } from '../../foundation/theme-provider';

/**
 * Created once at module scope. Building it inside render returns a new component
 * type every pass, which remounts the circle and drops the animation mid-flight.
 */
const AnimatedCircle = Animated.createAnimatedComponent(Circle);

export type MeterShape = 'bar' | 'ring';
export type MeterTone = 'brand' | 'positive' | 'negative' | 'neutral';

export type MeterProps = {
  value: number;
  max?: number;
  min?: number;
  shape?: MeterShape;
  tone?: MeterTone;
  label?: string;
  /** Text in the middle of a ring, or beside a bar. Defaults to a percentage. */
  valueLabel?: string;
  /** Hide the numeric readout. Only do this where the value is stated nearby. */
  showValue?: boolean;
  /** Fraction (0-1) past which the meter turns warning. */
  warnAt?: number;
  /** Fraction (0-1) past which the meter turns danger. */
  dangerAt?: number;
  /** Bar thickness, or ring stroke width. */
  thickness?: number;
  /** Ring diameter. Ignored by the bar shape. */
  size?: number;
  accessibilityLabel?: string;
  style?: StyleProp<ViewStyle>;
};

export function Meter({
  value,
  max = 100,
  min = 0,
  shape = 'bar',
  tone = 'brand',
  label,
  valueLabel,
  showValue = true,
  warnAt,
  dangerAt,
  thickness = shape === 'ring' ? 10 : 8,
  size = 120,
  accessibilityLabel,
  style,
}: MeterProps) {
  const t = useTokens();
  const [reduceMotion, setReduceMotion] = useState(false);
  const [progress] = useState(() => new Animated.Value(0));

  const range = max - min;
  const fraction = range === 0 ? 0 : Math.min(1, Math.max(0, (value - min) / range));

  useEffect(() => {
    let active = true;
    AccessibilityInfo.isReduceMotionEnabled().then((on) => active && setReduceMotion(on));
    const sub = AccessibilityInfo.addEventListener('reduceMotionChanged', setReduceMotion);
    return () => {
      active = false;
      sub.remove();
    };
  }, []);

  useEffect(() => {
    if (reduceMotion) {
      progress.setValue(fraction);
      return;
    }
    const animation = Animated.timing(progress, {
      toValue: fraction,
      duration: t.motion.duration.base,
      easing: Easing.out(Easing.cubic),
      // Width and stroke offset are layout properties, so this can't go native.
      useNativeDriver: false,
    });
    animation.start();
    return () => animation.stop();
  }, [fraction, progress, reduceMotion, t.motion.duration.base]);

  // Thresholds move the meter onto the reserved status palette; without them it
  // stays on the requested tone.
  const color = useMemo(() => {
    if (dangerAt != null && fraction >= dangerAt) return t.colors.feedbackError;
    if (warnAt != null && fraction >= warnAt) return t.colors.feedbackWarning;
    return tone === 'positive'
      ? t.colors.chartPositive
      : tone === 'negative'
        ? t.colors.chartNegative
        : tone === 'neutral'
          ? t.colors.textSecondary
          : t.colors.interactivePrimary;
  }, [dangerAt, warnAt, fraction, tone, t.colors]);

  const readout = valueLabel ?? `${Math.round(fraction * 100)}%`;
  const a11y = accessibilityLabel ?? label;

  const track = t.colors.surfaceInput;

  if (shape === 'ring') {
    const radius = (size - thickness) / 2;
    const circumference = 2 * Math.PI * radius;

    return (
      <View
        accessible
        accessibilityRole="progressbar"
        accessibilityLabel={a11y}
        accessibilityValue={{ min, max, now: value, text: readout }}
        style={[{ width: size, height: size, alignItems: 'center', justifyContent: 'center' }, style]}
      >
        <Svg width={size} height={size} style={{ position: 'absolute' }}>
          <Circle cx={size / 2} cy={size / 2} r={radius} stroke={track} strokeWidth={thickness} fill="none" />
          <AnimatedCircle
            cx={size / 2}
            cy={size / 2}
            r={radius}
            stroke={color}
            strokeWidth={thickness}
            strokeLinecap="round"
            fill="none"
            strokeDasharray={circumference}
            strokeDashoffset={progress.interpolate({
              inputRange: [0, 1],
              outputRange: [circumference, 0],
            })}
            // Start the sweep at 12 o'clock instead of 3.
            transform={`rotate(-90 ${size / 2} ${size / 2})`}
          />
        </Svg>
        {showValue ? (
          <View style={{ alignItems: 'center' }}>
            <Text
              style={{
                color: t.colors.textPrimary,
                fontFamily: t.fontFamilies.sans,
                fontSize: t.typography.title2.fontSize,
                lineHeight: t.typography.title2.lineHeight,
                fontWeight: '700',
              }}
            >
              {readout}
            </Text>
            {label ? (
              <Text
                numberOfLines={1}
                style={{
                  color: t.colors.textSecondary,
                  fontFamily: t.fontFamilies.sans,
                  fontSize: t.typography.bodySm.fontSize,
                  lineHeight: t.typography.bodySm.lineHeight,
                }}
              >
                {label}
              </Text>
            ) : null}
          </View>
        ) : null}
      </View>
    );
  }

  return (
    <View
      accessible
      accessibilityRole="progressbar"
      accessibilityLabel={a11y}
      accessibilityValue={{ min, max, now: value, text: readout }}
      style={[{ gap: t.spacing[1] }, style]}
    >
      {label || showValue ? (
        <View style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between' }}>
          {label ? (
            <Text
              numberOfLines={1}
              style={{
                flexShrink: 1,
                color: t.colors.textSecondary,
                fontFamily: t.fontFamilies.sans,
                fontSize: t.typography.bodySm.fontSize,
                lineHeight: t.typography.bodySm.lineHeight,
              }}
            >
              {label}
            </Text>
          ) : (
            <View />
          )}
          {showValue ? (
            <Text
              style={{
                color: t.colors.textPrimary,
                fontFamily: t.fontFamilies.sans,
                fontSize: t.typography.bodySm.fontSize,
                lineHeight: t.typography.bodySm.lineHeight,
                fontWeight: '600',
              }}
            >
              {readout}
            </Text>
          ) : null}
        </View>
      ) : null}
      <View
        style={{
          height: thickness,
          borderRadius: t.radii.full,
          backgroundColor: track,
          overflow: 'hidden',
        }}
      >
        <Animated.View
          style={{
            height: '100%',
            borderRadius: t.radii.full,
            backgroundColor: color,
            width: progress.interpolate({
              inputRange: [0, 1],
              outputRange: ['0%', '100%'],
            }),
          }}
        />
      </View>
    </View>
  );
}

